# খেলা কখন? কুইজ: প্রশ্ন তৈরির স্ক্রিপ্ট
# যাচাইযোগ্য, স্থির (ঐতিহাসিক) তথ্যের টেবিল থেকে প্রশ্ন বানায়; ভুল অপশন একই টেবিল থেকে আসে।
# চালানো: python3 quiz/build_questions.py  →  quiz/questions.json, quiz/questions.csv
import json, csv, random, os

rng = random.Random(2026)
BN = "০১২৩৪৫৬৭৮৯"
import re as _re
def poss(n):
    # বাংলা ষষ্ঠী: স্বরচিহ্ন বা স্বরবর্ণে শেষ হলে "র", ব্যঞ্জনে "ের"
    return n + ("র" if _re.search(r"[\u09BE-\u09CC\u0985-\u0994]$", n) else "ের")
def bn(x): return "".join(BN[int(c)] if c.isdigit() else c for c in str(x))
Q = []
def add(cat, diff, q, ans, pool, expl="", avoid=()):
    pool = [p for p in dict.fromkeys(pool) if p != ans and p not in avoid]
    if len(pool) < 3: raise SystemExit(f"distractor pool too small: {q}")
    opts = rng.sample(pool, 3) + [ans]
    rng.shuffle(opts)
    Q.append({"category": cat, "difficulty": diff, "question": q, "options": opts, "answer": opts.index(ans), "explanation": expl, "tpl": True})
def add_fixed(cat, diff, q, ans, wrong, expl=""):
    assert len(wrong) == 3 and ans not in wrong, q
    opts = list(wrong) + [ans]; rng.shuffle(opts)
    Q.append({"category": cat, "difficulty": diff, "question": q, "options": opts, "answer": opts.index(ans), "explanation": expl})

