print("total", len(Q))
from collections import Counter
print(Counter(q["category"] for q in Q), Counter(q["difficulty"] for q in Q))
# ঠিক ৫০০টি রাখি: প্রতিটি ধরন থেকে অনুপাতে, একই রকম টেমপ্লেট কম কম
TARGET = 500
if len(Q) > TARGET:
    # হাতে লেখা প্রশ্ন সব থাকে; ছাঁচের (টেবিল থেকে বানানো) প্রশ্ন থেকে বাকিটা, প্রতিটি ছাঁচ থেকে সমান হারে
    fixed = [q for q in Q if not q.get("tpl")]
    tpl = [q for q in Q if q.get("tpl")]
    need = TARGET - len(fixed)
    import re
    groups = {}
    for q in tpl: groups.setdefault(re.sub(r"[০-৯–]+", "#", q["question"]), []).append(q)
    ratio = need / len(tpl)
    picked = []
    for g in groups.values():
        k = max(1, round(len(g) * ratio)); picked += rng.sample(g, min(k, len(g)))
    rng.shuffle(picked)
    picked = picked[:need] if len(picked) >= need else picked + rng.sample([q for q in tpl if q not in picked], need - len(picked))
    order = {id(q): i for i, q in enumerate(Q)}
    Q[:] = sorted(fixed + picked, key=lambda q: order[id(q)])
# একই প্রশ্ন দুবার নয়
seen = set()
for q in Q:
    assert q["question"] not in seen, q["question"]; seen.add(q["question"])
    assert len(set(q["options"])) == 4, q
for i, q in enumerate(Q, 1): q["id"] = i; q.pop("tpl", None)
here = os.path.dirname(os.path.abspath(__file__))
json.dump([{"id": q["id"], **{k: q[k] for k in ("category","difficulty","question","options","answer","explanation")}} for q in Q],
          open(os.path.join(here, "questions.json"), "w"), ensure_ascii=False, indent=1)
with open(os.path.join(here, "questions.csv"), "w", newline="", encoding="utf-8-sig") as f:
    w = csv.writer(f)
    w.writerow(["id","বিষয়","কঠিনতা","প্রশ্ন","ক","খ","গ","ঘ","সঠিক উত্তর","ব্যাখ্যা"])
